/**
 * The conversation screen, with a thread above a composer (`design/archetypes/conversation-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/conversation-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  cell,
  derived,
  devWarning,
  elementRef,
  mountEffect,
  useMember,
  type Emitted,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/archetypes/conversation-page.module.css'
import { Button, type ButtonProps } from '../controls/Button'
import { Drawer, type DrawerProps } from '../overlays/Drawer'
import { PageHeader, type PageHeaderProps } from '../structure/PageHeader'
import { SplitPane, type SplitPaneProps } from '../layout/SplitPane'

/** The conversation screen, with a thread above a composer: the inputs it takes, by the React member's prop names. */
export interface ConversationPageProps {
  /**
   * The aside's name, used for the separator, the drawer's title and the toggle's label.
   */
  asideLabel?: string
  description?: string
  title: string
}

/** The conversation screen, with a thread above a composer. */
@Component({
  selector: 'pm-conversation-page',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate, Button, Drawer, PageHeader, SplitPane],
  // prettier-ignore
  template: `<ng-template pmSlot="actions" [pmSlotOf]="$"><ng-content select="[slot=actions]" /></ng-template>
<ng-template pmSlot="aside" [pmSlotOf]="$"><ng-content select="[slot=aside]" /></ng-template>
<ng-template pmSlot="composer" [pmSlotOf]="$"><ng-content select="[slot=composer]" /></ng-template>
<ng-template pmSlot="thread" [pmSlotOf]="$"><ng-content select="[slot=thread]" /></ng-template>
<!-- root -->
<div
[attr.class]="e1()"
[attr.data-aside]="e2()"
data-member="conversation-page"
[pmRef]="root"
><pm-page-header
[title]="e3()"
[description]="e4()"
>@if (e7()) {<ng-container ngProjectAs="[slot=actions]"><ng-container [pmSlotOutlet]="'actions'" [pmSlotOf]="$" pmSlotInto="actions" />
@if (e5()) {<pm-button
variant="outline"
tone="neutral"
size="sm"
icon="artifact"
[label]="e6()"
(click)="h1()"
></pm-button>}</ng-container>}</pm-page-header>
<!-- body -->
<div
[attr.class]="e8()"
>@if (e9()) {<pm-split-pane
[label]="e10()"
[defaultRatio]="e11()"
[startMin]="e12()"
[endMin]="e13()"
><ng-container ngProjectAs="[slot=start]"><!-- conversation -->
<div
[attr.class]="e14()"
><!-- thread -->
<div
[attr.class]="e15()"
><ng-container [pmSlotOutlet]="'thread'" [pmSlotOf]="$" pmSlotInto="start" /></div>
<!-- composer -->
<div
[attr.class]="e16()"
><ng-container [pmSlotOutlet]="'composer'" [pmSlotOf]="$" pmSlotInto="start" /></div></div></ng-container>
<ng-container ngProjectAs="[slot=end]"><!-- aside -->
<div
[attr.class]="e17()"
><ng-container [pmSlotOutlet]="'aside'" [pmSlotOf]="$" pmSlotInto="end" /></div></ng-container></pm-split-pane>} @else {<!-- conversation -->
<div
[attr.class]="e18()"
><!-- thread -->
<div
[attr.class]="e19()"
><ng-container [pmSlotOutlet]="'thread'" [pmSlotOf]="$" /></div>
<!-- composer -->
<div
[attr.class]="e20()"
><ng-container [pmSlotOutlet]="'composer'" [pmSlotOf]="$" /></div></div>}</div>
@if (e5()) {<pm-drawer
side="end"
size="lg"
[title]="e21()"
[open]="e22()"
(openChange)="h2($event)"
><!-- drawerAside -->
<div
[attr.class]="e23()"
><ng-container [pmSlotOutlet]="'aside'" [pmSlotOf]="$" pmSlotInto="default" /></div></pm-drawer>}</div>`,
})
export class ConversationPage {
  /**
   * The aside's name, used for the separator, the drawer's title and the toggle's label.
   */
  readonly asideLabel = input<ConversationPageProps['asideLabel']>(undefined)
  readonly description = input<ConversationPageProps['description']>(undefined)
  readonly title = input.required<ConversationPageProps['title']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      asideLabel: () => this.asideLabel(),
      description: () => this.description(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly narrow = cell(() => false)
  protected readonly asideOpen = cell(() => false)
  protected readonly root = elementRef<HTMLElement>()
  protected readonly measure = derived(() => () => {
    if (this.root.value === null) return
    const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
    const below = this.root.value.getBoundingClientRect().width < 48 * rem
    this.narrow.value = below
    if (!below) this.asideOpen.value = false
  })
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return styles.page
  }

  protected e2() {
    return this.$.filled('aside') ? (this.narrow.value ? 'drawer' : 'split') : undefined
  }

  protected e3(): PageHeaderProps['title'] {
    return this.$p.title
  }

  protected e4(): PageHeaderProps['description'] {
    return this.$p.description
  }

  protected e5() {
    return this.$.filled('aside') && this.narrow.value
  }

  protected e6(): ButtonProps['label'] {
    if (!(this.$.filled('aside') && this.narrow.value)) return undefined as never
    return this.$p.asideLabel ?? ''
  }

  protected h1(): void {
    if (!(this.$.filled('aside') && this.narrow.value)) return
    this.asideOpen.value = true
  }

  protected e7() {
    return this.$.filled('actions') || (this.$.filled('aside') && this.narrow.value)
  }

  protected e8() {
    return styles.body
  }

  protected e9() {
    return this.$.filled('aside') && !this.narrow.value
  }

  protected e10(): SplitPaneProps['label'] {
    if (!(this.$.filled('aside') && !this.narrow.value)) return undefined as never
    return this.$p.asideLabel ?? ''
  }

  protected e11(): SplitPaneProps['defaultRatio'] {
    if (!(this.$.filled('aside') && !this.narrow.value)) return undefined as never
    return 0.58
  }

  protected e12(): SplitPaneProps['startMin'] {
    if (!(this.$.filled('aside') && !this.narrow.value)) return undefined as never
    return 320
  }

  protected e13(): SplitPaneProps['endMin'] {
    if (!(this.$.filled('aside') && !this.narrow.value)) return undefined as never
    return 280
  }

  protected e14() {
    if (!(this.$.filled('aside') && !this.narrow.value)) return undefined as never
    return styles.conversation
  }

  protected e15() {
    if (!(this.$.filled('aside') && !this.narrow.value)) return undefined as never
    return styles.thread
  }

  protected e16() {
    if (!(this.$.filled('aside') && !this.narrow.value)) return undefined as never
    return styles.composer
  }

  protected e17() {
    if (!(this.$.filled('aside') && !this.narrow.value)) return undefined as never
    return styles.aside
  }

  protected e18() {
    if (this.$.filled('aside') && !this.narrow.value) return undefined as never
    return styles.conversation
  }

  protected e19() {
    if (this.$.filled('aside') && !this.narrow.value) return undefined as never
    return styles.thread
  }

  protected e20() {
    if (this.$.filled('aside') && !this.narrow.value) return undefined as never
    return styles.composer
  }

  protected e21(): DrawerProps['title'] {
    if (!(this.$.filled('aside') && this.narrow.value)) return undefined as never
    return this.$p.asideLabel ?? ''
  }

  protected e22(): DrawerProps['open'] {
    if (!(this.$.filled('aside') && this.narrow.value)) return undefined as never
    return this.asideOpen.value
  }

  protected h2($event: Emitted<Drawer['onOpenChange']>): void {
    if (!(this.$.filled('aside') && this.narrow.value)) return
    this.asideOpen.value = $event
  }

  protected e23() {
    if (!(this.$.filled('aside') && this.narrow.value)) return undefined as never
    return styles.drawerAside
  }

  private effect1(): void {
    this.release1?.()
    const run = () => {
      this.measure.value()
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.root.value]) if (element) resize?.observe(element)
    this.release1 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect2(): void {
    devWarning(
      Boolean(this.$.filled('aside')) && this.$p.asideLabel === undefined,
      'ConversationPage: an `aside` needs an `asideLabel`, which names the split’s separator, the drawer and its toggle.',
    )
  }
}
